{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the ruined city's edge.",
      "visual_description": "A cracked stone overlook above a broken skyline of toppled spires; ink-stained maps unrolled on a fallen column at dusk.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Oracle Lamp warns of the city's traps.",
      "visual_description": "A close-up of an oil lamp with a single glowing eye in its flame, casting long shadows over a torn royal banner.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the broken castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes slipping between rusted iron portcullis bars, key-wind tail still ticking.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver emerges from a shattered window.",
      "visual_description": "A figure in a clear diving helmet rising out of a tall broken pane as if from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara maps a path past the cursed tower.",
      "visual_description": "A leaning black tower wrapped in green witchfire smoke; Mara's brass compass spinning wildly above a chalk-marked map.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a winged beast echo overhead.",
      "visual_description": "Massive shadow sweeping across cracked rooftops; Oracle Lamp's flame bent sideways, eye narrowed in alarm.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "They find the Sleeping Tax Collector at a checkpoint.",
      "visual_description": "A plump official slumped over a ledger pillow inside a tilted toll booth, stamped papers fluttering from his sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrol clatters down the avenue.",
      "visual_description": "Tin Fox crouched behind a fallen statue, blue glass eyes reflecting marching armored silhouettes in the rain-slick street.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Glass Diver slips through a tall mirror.",
      "visual_description": "A grand cracked mirror in a ransacked hall, ripples spreading across its surface as the diver's reflective coat passes through.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The team reaches the magic door of the keep.",
      "visual_description": "A massive bronze door etched with shifting runes, Oracle Lamp's eye reading the glyphs while Mara sketches them down.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Tin Fox triggers the lock with a clever turn.",
      "visual_description": "Clockwork paws pressing rune-tiles in sequence, sparks of pale light tracing across the bronze door's surface.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, they find the captive they came for.",
      "visual_description": "A dim vaulted chamber with the Sleeping Tax Collector — yes, still dozing — chained to a desk piled with confiscated royal seals.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle Lamp warns the floor is a trap.",
      "visual_description": "Glowing eye flaring bright, illuminating thin pressure cracks spreading across the tiled floor under the official's chair.",
      "characters": ["oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Glass Diver pulls everyone through a stained window.",
      "visual_description": "Colored glass rippling like a pond as figures dive in, coat-tails trailing prisms across a collapsing throne room.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "They surface in the lantern-lit lower streets.",
      "visual_description": "Wet cobblestones, faces pressed nervously to shuttered windows above, the team dripping with mirror-light instead of water.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "A patrol blocks the road to the bridge.",
      "visual_description": "Tall armored figures with halberds silhouetted at the avenue's end, Tin Fox's tail winding tight to bolt past them.",
      "characters": ["tin_fox", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the cracked stone bridge.",
      "visual_description": "An arched bridge over a misty chasm, stones crumbling behind their heels; the Sleeping Tax Collector carried under one arm, still snoring.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the lamp's eye dims to a wink.",
      "visual_description": "Dawn breaking over distant ruined spires; the team silhouetted on a grassy ridge, Oracle Lamp's flame curling into a tired, satisfied wink.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

